 Here is an example of how you can implement a recursive function in C++ to generate the Fibonacci sequence:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

int fibonacci(int n, int a = 0, int b = 1) {
    if (n <= 0) throw invalid_argument("Number of elements must be positive.");
    if (n == 1) return a;
    return fibonacci(n - 1, b, a + b);
}

int main() {
    int num1, num2, numElements;

    cout << "Enter the first number in the sequence: ";
    cin >> num1;
    while (!isdigit(num1)) {
        cout << "Invalid input. Please enter a valid number: ";
        cin >> num1;
    }

    cout << "Enter the second number in the sequence: ";
    cin >> num2;
    while (!isdigit(num2)) {
        cout << "Invalid input. Please enter a valid number: ";
        cin >> num2;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;
    while (numElements <= 0) {
        cout << "Invalid input. Number of elements must be positive. Try again: ";
        cin >> numElements;
    }

    try {
        cout << num1 << ", " << num2;
        for (size_t i = 2; i < numElements; ++i) {
            int next = fibonacci(i);
            cout << ", " << next;
        }
        cout << endl;
    } catch (const invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }

    return 0;
}
```

